import '../models/guide.dart';

/// Konten Materi Belajar per kursus. Teks penjelasan tersedia dalam
/// bahasa UI 'id' dan 'en'.
List<KanaItem> _kana(String s) => s.trim().split(RegExp(r'\s+')).map((e) {
  final i = e.indexOf(':');
  return KanaItem(e.substring(0, i), e.substring(i + 1));
}).toList();

